const SOURCE = 'Chris0Jeky/Pulseboard:observatory';
export const HOST_CHECKER = 'observatory/check.mjs';
export const HOST_README = 'observatory/README.md';

/** One generated checker is shared by every host. Product-specific policy belongs in check.local.mjs. */
export function buildHostChecker() {
  return `/* SPDX-License-Identifier: GPL-3.0-only
 * Generated by Pulseboard Observatory. Do not edit this file.
 * Put product-specific assertions in observatory/check.local.mjs. */
import { createHash } from 'node:crypto';
import { existsSync, lstatSync, readFileSync, realpathSync } from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SOURCE = 'Chris0Jeky/Pulseboard:observatory';
const here = path.dirname(fileURLToPath(import.meta.url));
const root = realpathSync(path.resolve(here, '..'));
const lockPath = path.join(root, 'observatory.lock.json');
const sha256 = value => createHash('sha256').update(value).digest('hex');
const normalise = value => value.replaceAll('\\r\\n', '\\n');
function ownedFile(relative, label) {
  if (typeof relative !== 'string' || path.isAbsolute(relative) || relative.split(/[\\\\/]/).includes('..')) throw new Error(label + ' path leaves repository');
  const full = path.resolve(root, relative);
  if (full === root || !full.startsWith(root + path.sep)) throw new Error(label + ' path leaves repository');
  const stat = lstatSync(full, { throwIfNoEntry: false });
  if (!stat || !stat.isFile() || stat.isSymbolicLink()) throw new Error(label + ' is missing, not a file, or a symlink: ' + relative);
  const parent = realpathSync(path.dirname(full));
  if (parent !== root && !parent.startsWith(root + path.sep)) throw new Error(label + ' parent leaves repository: ' + relative);
  return full;
}
const lockStat = lstatSync(lockPath, { throwIfNoEntry: false });
if (!lockStat || !lockStat.isFile() || lockStat.isSymbolicLink()) throw new Error('observatory.lock.json is missing, not a file, or a symlink');
const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
if (lock.source !== SOURCE) throw new Error('Unexpected Observatory lock source');
let installs;
if (lock.installs && Object.getPrototypeOf(lock.installs) === Object.prototype) installs = lock.installs;
else if (typeof lock.target === 'string' && typeof lock.sha256 === 'string') installs = { [lock.target.split(/[\\\\/]/).join('/')]: { project: lock.project, sha256: lock.sha256 } };
else throw new Error('Unsupported Observatory lock shape');
const entries = Object.entries(installs).sort(([a], [b]) => a.localeCompare(b));
if (!entries.length) throw new Error('Observatory lock contains no installs');
const artifacts = entries.map(([target, owned]) => {
  if (!owned || typeof owned.project !== 'string' || !/^[a-f0-9]{64}$/.test(owned.sha256)) throw new Error('Invalid lock entry for ' + target);
  const full = ownedFile(target, 'Observatory artifact');
  const content = normalise(readFileSync(full, 'utf8'));
  const actual = sha256(content);
  if (actual !== owned.sha256) throw new Error('Integrity mismatch for ' + target + ': expected ' + owned.sha256 + ', got ' + actual);
  const leaked = content.split('\\n').find(line => /^(?:import|export)\\b/.test(line));
  if (leaked) throw new Error('Generated artifact contains a module statement: ' + leaked.slice(0, 60));
  if (/MAX_BYTES|MAX_BATCH/.test(content)) throw new Error('Generated artifact contains server-only constants');
  new vm.Script(content, { filename: target });
  return Object.freeze({ target, project: owned.project, sha256: actual, content });
});
const localPath = path.join(here, 'check.local.mjs');
if (existsSync(localPath)) {
  const localStat = lstatSync(localPath);
  if (!localStat.isFile() || localStat.isSymbolicLink()) throw new Error('observatory/check.local.mjs must be a regular file');
  const local = await import(pathToFileURL(localPath).href);
  const check = local.default ?? local.check;
  if (typeof check !== 'function') throw new Error('observatory/check.local.mjs must export a default function or check()');
  await check(Object.freeze({ root, source: SOURCE, lock: Object.freeze(lock), artifacts: Object.freeze(artifacts) }));
}
console.log(JSON.stringify({ source: SOURCE, targets: artifacts.map(artifact => artifact.target) }));
`;
}

/** Minimal host-side ownership notes. Existing host documentation is never overwritten. */
export function buildHostReadme(targets) {
  const normalised = [...new Set(targets.map(target => target.split(/[\\/]/).join('/')))].sort();
  const rules = [...normalised, HOST_CHECKER, 'observatory.lock.json'];
  return `# Pulseboard Observatory integration

The files listed in \`observatory.lock.json\` are generated by the central Pulseboard Observatory installer. Run \`node observatory/check.mjs\` in CI and before committing a regenerated artifact. The shared checker validates every target-keyed or legacy lock entry, normalises checkout CRLF before hashing, and rejects malformed generated scripts.

Keep product-specific checks in \`observatory/check.local.mjs\` as a default-exported function. The installer owns \`observatory/check.mjs\` and refuses to overwrite local edits. This README is updated only while it still matches the generated stub; host notes are preserved.

Pin generated bytes in the host repository's \`.gitattributes\`:

\`\`\`gitattributes
${rules.map(rule => `${rule.replaceAll(' ', '\\ ')} text eol=lf`).join('\n')}
\`\`\`

Collection remains disabled until the generated artifact contains the reviewed HTTPS endpoint and the host's privacy and activation gates pass.
`;
}

export { SOURCE };
